$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$root = (Get-Location).Path

$packagePath = Join-Path $root "package.json"
$zhPagePath = Join-Path $root "app\products\page.tsx"
$localePagePath = Join-Path $root "app\[locale]\products\page.tsx"

$requiredPaths = @(
  $packagePath,
  $zhPagePath,
  $localePagePath
)

foreach ($requiredPath in $requiredPaths) {
  if (-not (Test-Path -LiteralPath $requiredPath)) {
    throw "没有找到必要文件：$requiredPath"
  }
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupMap = @{}
$createdFiles = New-Object System.Collections.Generic.List[string]

function Backup-File {
  param([string]$Path)

  if (-not (Test-Path -LiteralPath $Path)) {
    return
  }

  if ($script:backupMap.ContainsKey($Path)) {
    return
  }

  $backupPath = $Path + "." + $stamp + ".bak"
  Copy-Item -LiteralPath $Path -Destination $backupPath -Force
  $script:backupMap[$Path] = $backupPath
  Write-Host "已备份：$backupPath" -ForegroundColor Yellow
}

function Write-Utf8NoBom {
  param(
    [string]$Path,
    [string]$Content
  )

  $directory = Split-Path -Parent $Path

  if (-not (Test-Path -LiteralPath $directory)) {
    New-Item -ItemType Directory -Path $directory -Force | Out-Null
  }

  if (-not (Test-Path -LiteralPath $Path)) {
    $script:createdFiles.Add($Path)
  } else {
    Backup-File -Path $Path
  }

  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}

function Decode-Base64Utf8 {
  param([string]$Encoded)

  $bytes = [System.Convert]::FromBase64String($Encoded)
  return [System.Text.Encoding]::UTF8.GetString($bytes)
}

function Ensure-SkeletonFallback {
  param(
    [string]$Path,
    [string]$LocaleExpression
  )

  $content = Get-Content -LiteralPath $Path -Raw -Encoding UTF8
  Backup-File -Path $Path

  if ($content -notmatch 'import\s+ProductPageSkeleton\s+from\s+["'']@/components/common/ProductPageSkeleton["'']') {
    $productImport = 'import ProductSelectionClient from "@/components/products/selection/ProductSelectionClient";'

    if (-not $content.Contains($productImport)) {
      throw "无法在页面中找到 ProductSelectionClient 引入：$Path"
    }

    $replacementImport = 'import ProductPageSkeleton from "@/components/common/ProductPageSkeleton";' + [Environment]::NewLine + $productImport
    $content = $content.Replace($productImport, $replacementImport)
  }

  if ($content -notmatch 'import\s+\{\s*Suspense\s*\}\s+from\s+["'']react["'']') {
    $firstImportIndex = $content.IndexOf("import ")

    if ($firstImportIndex -lt 0) {
      throw "无法在页面中找到 import 插入位置：$Path"
    }

    $content = $content.Insert(
      $firstImportIndex,
      'import { Suspense } from "react";' + [Environment]::NewLine + [Environment]::NewLine
    )
  }

  $content = [Regex]::Replace(
    $content,
    'fallback=\{\s*null\s*\}',
    'fallback={<ProductPageSkeleton variant="selection" />}'
  )

  if ($content -notmatch '<Suspense\b') {
    $clientPattern = 'return\s+<ProductSelectionClient\s+locale=\{' + [Regex]::Escape($LocaleExpression) + '\}\s*/>;'
    $clientStringPattern = 'return\s+<ProductSelectionClient\s+locale=["'']' + [Regex]::Escape($LocaleExpression) + '["'']\s*/>;'

    $replacement = @"
return (
    <Suspense fallback={<ProductPageSkeleton variant="selection" />}>
      <ProductSelectionClient locale={$LocaleExpression} />
    </Suspense>
  );
"@

    if ([Regex]::IsMatch($content, $clientPattern)) {
      $content = [Regex]::Replace($content, $clientPattern, $replacement.Trim(), 1)
    }
    elseif ([Regex]::IsMatch($content, $clientStringPattern)) {
      $stringReplacement = @"
return (
    <Suspense fallback={<ProductPageSkeleton variant="selection" />}>
      <ProductSelectionClient locale="$LocaleExpression" />
    </Suspense>
  );
"@

      $content = [Regex]::Replace(
        $content,
        $clientStringPattern,
        $stringReplacement.Trim(),
        1
      )
    }
    else {
      throw "无法在页面中找到 ProductSelectionClient 返回结构：$Path"
    }
  }

  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $content, $encoding)
}

