'@
  $content_4 = Decode-Base64Utf8 -Encoded ($content_4Base64.Trim())
  Write-Utf8NoBom -Path (Join-Path $root "app\\[locale]\\products\\loading.tsx") -Content $content_4

  $content_5Base64 = @'
aW1wb3J0IFByb2R1Y3RQYWdlU2tlbGV0b24gZnJvbSAiQC9jb21wb25lbnRzL2NvbW1vbi9Qcm9kdWN0UGFnZVNrZWxldG9uIjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIFByb2R1Y3REZXRhaWxMb2FkaW5nKCkgewogIHJldHVybiA8UHJvZHVjdFBhZ2VTa2VsZXRvbiB2YXJpYW50PSJkZXRhaWwiIC8+Owp9Cg==
'@
  $content_5 = Decode-Base64Utf8 -Encoded ($content_5Base64.Trim())
  Write-Utf8NoBom -Path (Join-Path $root "app\\products\\[category]\\[slug]\\loading.tsx") -Content $content_5

  Ensure-SkeletonFallback -Path $zhPagePath -LocaleExpression "zh"
